      "module_name": "Mathlib.Data.Real.Embedding",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : AddCommGroup M] [inst_1 : LinearOrder M] [IsOrderedAddMonoid M] [inst_3 : One M]\n  [ZeroLEOneClass M] [NeZero 1] {num : ℤ} {den : ℕ} {x : M}, num • 1 ≤ den • x → ∀ {n : ℤ}, x ≤ n • 1 → num ≤ n * ↑den"
    },
    {
      "name": "Mathlib.Tactic.FieldSimp.lt_eq_cancel_lt",
      "module_name": "Mathlib.Tactic.FieldSimp.Lemmas",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} [inst : MonoidWithZero M] [inst_1 : PartialOrder M] [PosMulStrictMono M] [PosMulReflectLT M]\n  {e₁ e₂ f₁ f₂ L : M}, e₁ = L * f₁ → e₂ = L * f₂ → 0 < L → (e₁ < e₂) = (f₁ < f₂)"
    },
    {
      "name": "LucasLehmer.order_ineq",
      "module_name": "Mathlib.NumberTheory.LucasLehmer",
      "kind": "theorem",
      "type": "∀ (p' : ℕ), lucasLehmerResidue (p' + 2) = 0 → 2 ^ (p' + 2) < ↑(LucasLehmer.q (p' + 2)) ^ 2"
    },
    {
      "name": "Finset.divConst_le_mulConst_sq",
      "module_name": "Mathlib.Combinatorics.Additive.DoublingConst",
      "kind": "theorem",
      "type": "∀ {G : Type u_1} [inst : Group G] [inst_1 : DecidableEq G] {A : Finset G}, A.divConst A ≤ A.mulConst A ^ 2"
    }
  ]
